head.script:
scwin.onpageload = function () {
};

/**
 * 버튼 [iframePopup]
 */
scwin.btn_exam4_1_onclick = function (e) {
    var options = {
        type: "iframePopup",
        id: "popup_exam_iframePopup",
        height: "300",
        top: 50,
        left: 0,
        popupName: "popup_exam1",
        dataObject: {
            type: "json",
            data: {
                "type": "iframePopup"
            },
            name: "exam_param"
        },
        useControl: true,
        useATagBtn: true
    };

    $p.openPopup("openPopup_options_useATagBtn_WESE-482_(WSQ-5394)_sub.xml", options);
};

/**
 * 버튼 [wframePopup]
 */
scwin.btn_exam4_2_onclick = function (e) {
    var options = {
        type: "wframePopup",
        id: "popup_exam_wframePopup",
        height: "300",
        top: 100,
        left: 50,
        popupName: "popup_exam2",
        dataObject: {
            type: "json",
            data: {
                "type": "wframePopup"
            },
            name: "exam_param"
        },
        useControl: true,
        useATagBtn: true
    };

    $p.openPopup("openPopup_options_useATagBtn_WESE-482_(WSQ-5394)_sub.xml", options);
};

/**
 * 버튼 [browserPopup]
 */
scwin.btn_exam4_3_onclick = function (e) {
    var options = {
        type: "browserPopup",
        id: "popup_exam3",
        width: "300px",
        height: "80px",
        top: 0,
        left: 0,
        popupName: "popup_exam3",
        dataObject: {
            type: "json",
            data: {
                "type": "browserPopup"
            },
            name: "exam_param"
        },
        useControl: true,
        useATagBtn: true
    };

    $p.openPopup("openPopup_options_useATagBtn_WESE-482_(WSQ-5394)_sub.xml", options);
};

scwin.btn_close_onclick = function (e) {
    var popList = $p.getAllPopupList();
    for (var i = popList.length - 1; i >= 0; i--) {
        $p.closePopup(popList[i].id);  // 열려있는 모든 popup을 닫는다. 닫을 때마다 popList가 제거되므로 array를 역순으로 돌아야 한다.
    }
};

	scwin.isWithinPercent = function(checkValue, baseValue, percentage){			
		const margin = baseValue * (percentage / 100);
		return (checkValue >= baseValue - margin) && (checkValue <= baseValue + margin);				
	}
	scwin.checkVal = function() {
		const offsetLeft = WebSquare.wUnit.getDomById('popup_exam_wframePopup_header_control').offsetLeft
		return scwin.isWithinPercent(offsetLeft, 438, 2);
	}	
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_exam4_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "300");		

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
